    loc={v: next(((r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==v),None) for v in (1,2,3,6)}
    # Each marker draws a motif: 1 repeats up-right; 2 makes a horizontal bar;
    # 6 launches a diagonal 4 trail, while 3 contributes a short vertical trail.
    if loc[1]:
        r,c=loc[1]
        for j in (c+1,c+2):
            if j<W and g[r][j]==0:g[r][j]=5
        if r>0 and c+2<W:g[r-1][c+2]=1
    if loc[2]:
        r,c=loc[2]
        for j in range(max(0,c-4),c):
            if g[r][j]==0:g[r][j]=5
        if c-4>=0:g[r][c-4]=2
    if loc[6]:
        r,c=loc[6]
        for k in range(1,min(c+1,H-r)):
            if g[r+k][c-k]==0:g[r+k][c-k]=4
    if loc[3]:
        r,c=loc[3]
        # Repeated 3 one row below; 5 between them.
        if r+3<H:
            g[r+3][c]=3
            for rr in (r+1,r+2):
                if g[rr][c]==0:g[rr][c]=5
    return g
