def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    pos={v: next(((r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==v),None) for v in (1,2,3,6)}
    # Marker 1: two 5s to the right, and a 1 above the far tip.
    if pos[1]:
        r,c=pos[1]
        for x in (c+1,c+2):
            if x<w and g[r][x]==0: g[r][x]=5
        if r>0 and c+2<w: g[r-1][c+2]=1
    # Marker 2: four-cell leftward 5 bar, with a 2 at the far end.
    if pos[2]:
        r,c=pos[2]
        if c>=4:
            for x in range(c-3,c):
                if g[r][x]==0: g[r][x]=5
            g[r][c-4]=2
    # Marker 3: two 5s below, followed by a repeated 3.
    if pos[3]:
        r,c=pos[3]
        for y in (r+1,r+2):
            if y<h and g[y][c]==0: g[y][c]=5
        if r+3<h: g[r+3][c]=3
    # Marker 6: upward vertical 5s capped by 6, plus diagonal 4s down-left.
    if pos[6]:
        r,c=pos[6]
        for y in range(r-1,0,-1):
            if g[y][c]==0: g[y][c]=5
        if r>0: g[0][c]=6
        for d in range(1,min(c+1,h-r)):
            if g[r+d][c-d]==0: g[r+d][c-d]=4
    # Where a 2 horizontal trail meets a 6 vertical ray, make the crossing 4.
    if pos[2] and pos[6]:
        r,c=pos[2]; r6,c6=pos[6]
        if r==r6 and c-4<=c6<c: g[r][c6]=4
    return g
