def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    pos = {v: next(((r, c) for r, row in enumerate(grid) for c, x in enumerate(row) if x == v), None)
           for v in (1, 2, 3, 6)}

    # 1: two 5s rightward; repeat 1 two columns right and one row up.
    if pos[1]:
        r, c = pos[1]
        for d in (1, 2):
            if c + d < w and g[r][c + d] == 0:
                g[r][c + d] = 5
        if r > 0 and c + 2 < w:
            g[r - 1][c + 2] = 1

    # 2: a four-cell left extension, ending in a duplicate 2.
    if pos[2]:
        r, c = pos[2]
        if c >= 4:
            g[r][c - 4] = 2
            for x in range(c - 3, c):
                if g[r][x] == 0:
                    g[r][x] = 5

    # 3: two 5s down, then a repeated 3.
    if pos[3]:
        r, c = pos[3]
        for d in (1, 2):
            if r + d < h and g[r + d][c] == 0:
                g[r + d][c] = 5
        if r + 3 < h:
            g[r + 3][c] = 3

    # 6: six-cell upward extension, capped by a duplicate 6.
    if pos[6]:
        r, c = pos[6]
        if r >= 6:
            top = r - 6
            g[top][c] = 6
            for rr in range(top + 1, r):
                if g[rr][c] == 0:
                    g[rr][c] = 5

    return g
